-- Safe additive MD3 separation; historical identifiers and prices remain intact.
DROP INDEX IF EXISTS "ServiceDefinition_serviceId_unique";
ALTER TABLE "ServiceReservation" ADD COLUMN IF NOT EXISTS "quantity" INTEGER NOT NULL DEFAULT 1;
ALTER TABLE "ServiceReservation" ADD COLUMN IF NOT EXISTS "expiresAt" TIMESTAMPTZ(3);
CREATE TABLE IF NOT EXISTS "CommerceService" ("id" TEXT NOT NULL PRIMARY KEY,"sourceId" TEXT UNIQUE,"ownerId" TEXT,"vendorId" TEXT,"body" JSONB NOT NULL,"version" INTEGER NOT NULL DEFAULT 1,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "CommerceService_sourceId_fkey" FOREIGN KEY ("sourceId") REFERENCES "ServiceItem"("id") ON DELETE RESTRICT,CONSTRAINT "CommerceService_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id") ON DELETE RESTRICT,CONSTRAINT "CommerceService_vendorId_fkey" FOREIGN KEY ("vendorId") REFERENCES "Vendor"("id") ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS "CommerceOffer" ("id" TEXT NOT NULL PRIMARY KEY,"serviceId" TEXT NOT NULL,"body" JSONB NOT NULL,"version" INTEGER NOT NULL DEFAULT 1,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "CommerceOffer_serviceId_fkey" FOREIGN KEY ("serviceId") REFERENCES "CommerceService"("id") ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS "CommerceOfferVersion" ("id" TEXT NOT NULL PRIMARY KEY,"offerId" TEXT NOT NULL,"version" INTEGER NOT NULL,"snapshot" JSONB NOT NULL,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "CommerceOfferVersion_offerId_fkey" FOREIGN KEY ("offerId") REFERENCES "CommerceOffer"("id") ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS "CommercePackage" ("id" TEXT NOT NULL PRIMARY KEY,"ownerId" TEXT NOT NULL,"body" JSONB NOT NULL,"version" INTEGER NOT NULL DEFAULT 1,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "CommercePackage_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id") ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS "CommercePackageItem" ("id" TEXT NOT NULL PRIMARY KEY,"packageId" TEXT NOT NULL,"offerId" TEXT NOT NULL,"body" JSONB NOT NULL,CONSTRAINT "CommercePackageItem_packageId_fkey" FOREIGN KEY ("packageId") REFERENCES "CommercePackage"("id") ON DELETE RESTRICT,CONSTRAINT "CommercePackageItem_offerId_fkey" FOREIGN KEY ("offerId") REFERENCES "CommerceOffer"("id") ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS "CommercePackageVersion" ("id" TEXT NOT NULL PRIMARY KEY,"packageId" TEXT NOT NULL,"version" INTEGER NOT NULL,"snapshot" JSONB NOT NULL,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "CommercePackageVersion_packageId_fkey" FOREIGN KEY ("packageId") REFERENCES "CommercePackage"("id") ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS "CommerceCart" ("userId" TEXT NOT NULL PRIMARY KEY,"body" JSONB NOT NULL,"version" INTEGER NOT NULL DEFAULT 1,"updatedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "CommerceCart_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS "CommerceOrder" ("id" TEXT NOT NULL PRIMARY KEY,"customerId" TEXT NOT NULL,"number" TEXT NOT NULL UNIQUE,"body" JSONB NOT NULL,"version" INTEGER NOT NULL DEFAULT 1,"idempotencyKey" TEXT NOT NULL UNIQUE,"requestHash" TEXT NOT NULL,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "CommerceOrder_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "User"("id") ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS "CommerceOrderItem" ("id" TEXT NOT NULL PRIMARY KEY,"orderId" TEXT NOT NULL,"serviceId" TEXT NOT NULL,"offerId" TEXT NOT NULL,"packageId" TEXT,"snapshot" JSONB NOT NULL,"body" JSONB NOT NULL,"version" INTEGER NOT NULL DEFAULT 1,CONSTRAINT "CommerceOrderItem_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "CommerceOrder"("id") ON DELETE RESTRICT,CONSTRAINT "CommerceOrderItem_serviceId_fkey" FOREIGN KEY ("serviceId") REFERENCES "CommerceService"("id") ON DELETE RESTRICT,CONSTRAINT "CommerceOrderItem_offerId_fkey" FOREIGN KEY ("offerId") REFERENCES "CommerceOffer"("id") ON DELETE RESTRICT,CONSTRAINT "CommerceOrderItem_packageId_fkey" FOREIGN KEY ("packageId") REFERENCES "CommercePackage"("id") ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS "CommerceFulfillmentGroup" ("id" TEXT NOT NULL PRIMARY KEY,"orderId" TEXT NOT NULL,"managerId" TEXT NOT NULL,"body" JSONB NOT NULL,CONSTRAINT "CommerceFulfillmentGroup_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "CommerceOrder"("id") ON DELETE RESTRICT,CONSTRAINT "CommerceFulfillmentGroup_managerId_fkey" FOREIGN KEY ("managerId") REFERENCES "User"("id") ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS "CommerceBooking" ("id" TEXT NOT NULL PRIMARY KEY,"orderItemId" TEXT NOT NULL UNIQUE,"requestId" TEXT NOT NULL UNIQUE,"status" TEXT NOT NULL,"fulfillmentStatus" TEXT NOT NULL DEFAULT 'NOT_STARTED',"body" JSONB NOT NULL,CONSTRAINT "CommerceBooking_orderItemId_fkey" FOREIGN KEY ("orderItemId") REFERENCES "CommerceOrderItem"("id") ON DELETE RESTRICT,CONSTRAINT "CommerceBooking_requestId_fkey" FOREIGN KEY ("requestId") REFERENCES "ServiceRequest"("id") ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS "CommerceTransfer" ("id" TEXT NOT NULL PRIMARY KEY,"orderId" TEXT NOT NULL,"kind" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'PENDING',"amount" INTEGER NOT NULL,"reference" TEXT NOT NULL UNIQUE,"makerId" TEXT NOT NULL,"checkerId" TEXT,"body" JSONB NOT NULL,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "CommerceTransfer_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "CommerceOrder"("id") ON DELETE RESTRICT,CONSTRAINT "CommerceTransfer_makerId_fkey" FOREIGN KEY ("makerId") REFERENCES "User"("id") ON DELETE RESTRICT,CONSTRAINT "CommerceTransfer_checkerId_fkey" FOREIGN KEY ("checkerId") REFERENCES "User"("id") ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS "CommerceRelationship" ("id" TEXT NOT NULL PRIMARY KEY,"serviceId" TEXT NOT NULL,"relatedServiceId" TEXT NOT NULL,"kind" TEXT NOT NULL,"body" JSONB NOT NULL,CONSTRAINT "CommerceRelationship_serviceId_fkey" FOREIGN KEY ("serviceId") REFERENCES "CommerceService"("id") ON DELETE RESTRICT,CONSTRAINT "CommerceRelationship_relatedServiceId_fkey" FOREIGN KEY ("relatedServiceId") REFERENCES "CommerceService"("id") ON DELETE RESTRICT);
CREATE INDEX IF NOT EXISTS "CommerceOffer_serviceId_idx" ON "CommerceOffer"("serviceId");
CREATE INDEX IF NOT EXISTS "CommerceOrder_customerId_idx" ON "CommerceOrder"("customerId");
CREATE INDEX IF NOT EXISTS "CommerceOrderItem_orderId_idx" ON "CommerceOrderItem"("orderId");
CREATE INDEX IF NOT EXISTS "CommerceFulfillmentGroup_managerId_idx" ON "CommerceFulfillmentGroup"("managerId");
CREATE INDEX IF NOT EXISTS "CommerceTransfer_orderId_idx" ON "CommerceTransfer"("orderId");
CREATE INDEX IF NOT EXISTS "CommerceRelationship_serviceId_idx" ON "CommerceRelationship"("serviceId");
CREATE UNIQUE INDEX IF NOT EXISTS "CommerceOfferVersion_offerId_version_key" ON "CommerceOfferVersion"("offerId","version");
CREATE UNIQUE INDEX IF NOT EXISTS "CommercePackageVersion_packageId_version_key" ON "CommercePackageVersion"("packageId","version");
CREATE UNIQUE INDEX IF NOT EXISTS "CommerceFulfillmentGroup_orderId_managerId_key" ON "CommerceFulfillmentGroup"("orderId","managerId");
CREATE UNIQUE INDEX IF NOT EXISTS "CommerceRelationship_serviceId_relatedServiceId_kind_key" ON "CommerceRelationship"("serviceId","relatedServiceId","kind");
INSERT INTO "CommerceService" ("id","sourceId","ownerId","vendorId","body") SELECT s."id",s."id",v."userId",s."vendorId",jsonb_build_object('titleAr',s."titleAr",'descriptionAr',s."descriptionAr",'categoryId',s."categoryId",'subcategoryId',s."subcategoryId",'artistId',s."artistId",'kind','BOOKABLE','images',s."images",'videoUrls',s."videoUrls",'previewAudioUrl',s."previewAudioUrl",'cities',to_jsonb(ARRAY[s."cityId"] || v."serviceAreas"),'published',s."isPublished",'approved',v."status"='ACTIVE','managerIds',CASE WHEN v."userId" IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(v."userId") END,'resourceIds','[]'::jsonb,'requirementsAr','') FROM "ServiceItem" s JOIN "Vendor" v ON v."id"=s."vendorId" ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommerceService" ("id","ownerId","body") SELECT 'platform:'||d."id",d."body"->'managerIds'->>0,(d."body"-'policy'-'shares'-'serviceId'-'typeId') || jsonb_build_object('kind','BOOKABLE','published',COALESCE((d."body"->>'enabled')::boolean,false),'approved',true,'images','[]'::jsonb) FROM "ServiceDefinition" d WHERE d."kind"='OFFERING' AND d."body"->>'serviceId' IS NULL ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommerceOffer" ("id","serviceId","body","version") SELECT d."id",COALESCE(d."body"->>'serviceId','platform:'||d."id"),d."body"||jsonb_build_object('nameAr',d."body"->>'titleAr','allowPackages',false,'validFrom',null,'validUntil',null,'holdMinutes',0),d."version" FROM "ServiceDefinition" d JOIN "CommerceService" s ON s."id"=COALESCE(d."body"->>'serviceId','platform:'||d."id") WHERE d."kind"='OFFERING' ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommerceOffer" ("id","serviceId","body") SELECT 'legacy-offer:'||s."id",s."id",jsonb_build_object('nameAr','خيار الشراء الأساسي','enabled',s."isPublished",'allowPackages',false,'holdMinutes',0,'managerIds',c."body"->'managerIds','resourceIds','[]'::jsonb,'shares',CASE WHEN c."ownerId" IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(jsonb_build_object('managerId',c."ownerId",'bps',10000)) END,'policy',jsonb_build_object('baseAmount',s."price"::bigint*100,'pricingMode',CASE WHEN s."priceType"='PER_PERSON' THEN 'GUEST' WHEN s."priceType"='STARTING_AT' THEN 'STARTING_AT' ELSE 'FIXED' END,'durationMinutes',s."executionDurationHours"*60,'maxDurationMinutes',GREATEST(1440,s."executionDurationHours"*60))) FROM "ServiceItem" s JOIN "CommerceService" c ON c."id"=s."id" WHERE NOT EXISTS (SELECT 1 FROM "CommerceOffer" o WHERE o."serviceId"=s."id") ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommerceOffer" ("id","serviceId","body") SELECT 'legacy-package-offer:'||p."id",s."id",jsonb_build_object('nameAr',p."nameAr",'termsAr',COALESCE(p."descriptionAr",''),'enabled',s."isPublished",'allowPackages',false,'holdMinutes',0,'model','FIXED','managerIds',c."body"->'managerIds','resourceIds','[]'::jsonb,'shares',CASE WHEN c."ownerId" IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(jsonb_build_object('managerId',c."ownerId",'bps',10000)) END,'policy',jsonb_build_object('baseAmount',p."price"::bigint*100,'pricingMode','FIXED','durationMinutes',COALESCE(p."durationHours",s."executionDurationHours")*60,'maxDurationMinutes',GREATEST(1440,COALESCE(p."durationHours",s."executionDurationHours")*60))) FROM "ServicePackage" p JOIN "ServiceItem" s ON s."id"=p."serviceId" JOIN "CommerceService" c ON c."id"=s."id" ON CONFLICT ("id") DO NOTHING;
INSERT INTO "CommerceOfferVersion" ("id","offerId","version","snapshot") SELECT o."id"||':v'||o."version",o."id",o."version",o."body" FROM "CommerceOffer" o ON CONFLICT DO NOTHING;
INSERT INTO "ServiceDefinition" ("id","kind","body") SELECT o."id",'OFFERING',o."body" || jsonb_build_object('commerceServiceId',s."id",'serviceId',s."sourceId",'titleAr',s."body"->>'titleAr','descriptionAr',s."body"->>'descriptionAr','categoryId',s."body"->>'categoryId','subcategoryId',s."body"->>'subcategoryId','cities',s."body"->'cities','typeId','standard','deliveryModel',CASE WHEN s."vendorId" IS NULL THEN 'PLATFORM' ELSE 'VENDOR' END) FROM "CommerceOffer" o JOIN "CommerceService" s ON s."id"=o."serviceId" ON CONFLICT ("id") DO UPDATE SET "body"="ServiceDefinition"."body" || jsonb_build_object('commerceServiceId',EXCLUDED."body"->>'commerceServiceId');
